# Correr desde la raiz del repo (...\Contratos).
$ErrorActionPreference = 'Stop'
function Write-FileFromBase64([string]$Path,[string]$B64){
  $dir = Split-Path $Path -Parent; if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  $bytes = [Convert]::FromBase64String(($B64 -replace '\s',''))
  [IO.File]::WriteAllBytes((Join-Path (Get-Location) $Path), $bytes); Write-Host "OK $Path" }
if (-not (Test-Path 'frontend\src\components\Layout.jsx')) { Write-Host 'Corre este script desde la carpeta Contratos (raiz del repo).' -ForegroundColor Red; exit 1 }
